const BY_ID = Object.fromEntries(CHARACTERS.map((c) => [c.id, c]));

const VARS = {
  primary: '--av-primary',
  secondary: '--av-secondary',
  accent: '--av-accent',
  background: '--av-bg',
  ink: '--av-ink',
  skin: '--av-skin',
};

const FACE_ATTR = { eyes: 'data-eyes', mouth: 'data-mouth', accessory: 'data-acc' };

/**
 * Apply face options to a Bits <svg>. Unset keys use that Bit's defaults.
 * face: { eyes, mouth, accessory, cheeks }  (cheeks: boolean)
 */
export function applyFace(svg, face = {}) {
  const def = BY_ID[svg.getAttribute('data-character')]?.face;
  if (!def) return;
  for (const [key, attr] of Object.entries(FACE_ATTR)) {
    const v = face?.[key] ?? def[key];
    svg.setAttribute(attr, FACE_OPTIONS[key].includes(v) ? v : def[key]);
  }
  svg.setAttribute('data-cheeks', face?.cheeks === false ? 'off' : 'on');
}

/** Raw SVG markup for a character (default colorway, idle). */
export function avatarMarkup(id) {
  const c = BY_ID[id];
  if (!c) throw new Error(`Unknown avatar "${id}". Try: ${Object.keys(BY_ID).join(', ')}`);
  return c.svg;
}

/** Resolve a theme key plus optional overrides into a flat color map. */
export function resolveColors(theme = 'original', overrides = null) {
  const base = typeof theme === 'string' ? (THEMES[theme]?.colors ?? {}) : (theme ?? {});
  return { ...base, ...(overrides ?? {}) };
}

/** Apply a colorway to an avatar <svg>. Unset keys fall back to the character defaults. */
export function applyColors(svg, theme = 'original', overrides = null) {
  const colors = resolveColors(theme, overrides);
  for (const [key, prop] of Object.entries(VARS)) {
    if (colors[key]) svg.style.setProperty(prop, colors[key]);
    else svg.style.removeProperty(prop);
  }
}

/**
 * Render an interactive avatar into `host`.
 * Options: character, theme, colors (overrides), state, background (bool),
 *          face ({ eyes, mouth, accessory, cheeks } for Bits),
 *          trackPointer (eyes follow the pointer), onPoke(characterId).
 */
export function mountAvatar(host, opts = {}) {
  let {
    character = 'lobster',
    theme = 'original',
    colors = null,
    state = 'idle',
    background = true,
    face = {},
    trackPointer = true,
    onPoke = null,
  } = opts;
  let svg = null;

  const render = () => {
    host.innerHTML = avatarMarkup(character);
    svg = host.querySelector('svg');
    svg.style.width = '100%';
    svg.style.height = '100%';
    svg.style.display = 'block';
    svg.setAttribute('data-state', state);
    svg.setAttribute('data-bg', background ? 'on' : 'off');
    applyColors(svg, theme, colors);
    applyFace(svg, face);
  };

  const lookAt = (x, y) => {
    if (!svg) return;
    svg.style.setProperty('--lx', Math.max(-1, Math.min(1, x)).toFixed(3));
    svg.style.setProperty('--ly', Math.max(-1, Math.min(1, y)).toFixed(3));
  };

  const onMove = (e) => {
    if (!svg) return;
    const r = svg.getBoundingClientRect();
    const reach = Math.max(r.width, 120) * 1.6;
    lookAt((e.clientX - (r.left + r.width / 2)) / reach, (e.clientY - (r.top + r.height * 0.45)) / reach);
  };
  const onLeave = () => lookAt(0, 0);

  const poke = () => {
    if (!svg) return;
    svg.classList.remove('bh-poke');
    void svg.getBoundingClientRect(); // restart the animation
    svg.classList.add('bh-poke');
    onPoke?.(character);
  };
  const onAnimEnd = (e) => {
    if (e.animationName === 'bh-squish') svg?.classList.remove('bh-poke');
  };

  render();
  host.addEventListener('pointerdown', poke);
  host.addEventListener('animationend', onAnimEnd);
  if (trackPointer) {
    window.addEventListener('pointermove', onMove, { passive: true });
    document.addEventListener('pointerleave', onLeave);
  }

  return {
    get element() { return svg; },
    get state() { return state; },
    setState(next) {
      if (!STATES.includes(next)) throw new Error(`Unknown state "${next}"`);
      state = next;
      svg.setAttribute('data-state', next);
    },
    setTheme(nextTheme, overrides = null) {
      theme = nextTheme;
      colors = overrides;
      applyColors(svg, theme, colors);
    },
    setCharacter(id, nextFace = {}) {
      character = id;
      face = nextFace;
      render();
    },
    /** Bits only. Merges into the current face; pass null for a key to restore its default. */
    setFace(next = {}) {
      face = { ...face, ...next };
      applyFace(svg, face);
    },
    get face() { return { ...face }; },
    setBackground(on) {
      background = !!on;
      svg.setAttribute('data-bg', background ? 'on' : 'off');
    },
    lookAt,
    poke,
    destroy() {
      host.removeEventListener('pointerdown', poke);
      host.removeEventListener('animationend', onAnimEnd);
      window.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerleave', onLeave);
      host.innerHTML = '';
      svg = null;
    },
  };
}
